            segs = tuple(tpl.segments_utc(day, self.tz))
            idx = np.array([i for i, t in enumerate(self.grid) if any(s <= t < e for s, e in segs)], dtype=int)
            if not len(idx):
                continue
            hours = sum((e - s).total_seconds() for s, e in segs) / 3600
            start = segs[0][0]
            brk = []
            if hours >= self.break_min_shift:
                lo, hi = self.window
                for i in idx:
                    t = self.grid[i]
                    for k, (s, e) in enumerate(segs):
                        if s <= t and t + self.break_len <= e and timedelta(hours=lo) <= t - start <= timedelta(hours=hi):
                            brk.append((int(i), k))
            out.append(Option(day, tpl, segs, idx, start, segs[-1][1], hours, tuple(brk)))
        return out


def place_breaks(ctx: Ctx, slots: list[tuple[str, Option]], rule: str):
    """Break start (grid index) for each slot, and gross / on-break counts per queue."""
    gross = {q: np.zeros(ctx.n) for q in ctx.queues}
    for q, o in slots:
        gross[q][o.idx] += 1
    brk = np.zeros((len(ctx.queues), ctx.n))
    qi = {q: i for i, q in enumerate(ctx.queues)}
    chosen: list = [None] * len(slots)
    surplus = {q: gross[q] - ctx.required[q] for q in ctx.queues}
    order = sorted(range(len(slots)), key=lambda i: (slots[i][1].start, slots[i][0], slots[i][1].tpl.id))
    for i in order:
        q, o = slots[i]
        if not o.breaks:
            continue
        s, k = surplus[q], brk[qi[q]]
        if rule == "midpoint":
            mid = o.start + timedelta(hours=o.hours / 2)
            pick = min(o.breaks, key=lambda b: (abs((ctx.grid[b[0]] - mid).total_seconds()), b[0]))
        else:
            best = max(s[b[0]] for b in o.breaks)
            tied = [b for b in o.breaks if s[b[0]] == best]
            pick = min(tied, key=lambda b: (k[b[0]] - s[b[0]] + gross[q][b[0]], b[0]))   # least net slack used
            pick = min(tied, key=lambda b: (k[b[0]], b[0]))
        chosen[i] = pick
        brk[qi[q], pick[0]] += 1
    return chosen, gross, {q: brk[qi[q]] for q in ctx.queues}


def evaluate_plan(ctx: Ctx, slots, rule: str) -> tuple[float, dict]:
    chosen, gross, brk = place_breaks(ctx, slots, rule)
    hours = sum(o.hours for _, o in slots)
    short = {}
    miss = 0.0
    for q in ctx.queues:
        net = gross[q] - brk[q]
        d = np.maximum(0.0, ctx.required[q] - net)
        n_short = int(((d > 0) & ctx.demand[q]).sum())
        floor_gap = np.maximum(0.0, ctx.floor[q] - gross[q])
        short[q] = n_short
        miss += float(d[ctx.demand[q]].sum()) + 3.0 * float(floor_gap.sum())
    cost = hours + SHORT_PRICE * miss
    return cost, {"hours": hours, "short": short, "gross": gross, "brk": brk, "chosen": chosen}


# --- plan construction ---------------------------------------------------------------------------------

def greedy_cover(ctx: Ctx, target: dict) -> list[tuple[str, Option]]:
    """Cover `target` (agents per interval per queue) with templates, queue by queue, day by day."""
    slots = []
    for q in ctx.queues:
        have = np.zeros(ctx.n)
        for day in ctx.days:
            opts = ctx.options[day]
            while True:
                best, best_score = None, 0.0
                unmet = np.maximum(0.0, target[q] - have)
                for o in opts:
                    u = float(np.minimum(1.0, unmet[o.idx]).sum())
                    if u <= 0:
                        continue
                    score = u / len(o.idx) + 1e-3 * u      # share of the template that is useful
                    if score > best_score + 1e-12:
                        best, best_score = o, score
                if best is None:
                    break
                slots.append((q, best))
                have[best.idx] += 1
    return slots


def plan_week(ctx: Ctx, banned: set | None = None) -> list[tuple[str, Option]]:
    rule = ctx.cfg.get("break_rule", "midpoint")
    banned = banned or set()
    bump = {q: np.zeros(ctx.n) for q in ctx.queues}
    best_slots, best_cost = None, float("inf")
    slots = []
    for _ in range(6):
        target = {q: ctx.need[q] + bump[q] for q in ctx.queues}
        slots = greedy_cover(ctx, target)
        cost, info = evaluate_plan(ctx, slots, rule)
        if cost < best_cost:
            best_slots, best_cost = list(slots), cost
        if not any(info["short"].values()):
            break
        for q in ctx.queues:
            net = info["gross"][q] - info["brk"][q]
            bump[q] += np.maximum(0.0, ctx.required[q] - net)
    slots = best_slots
    return local_search(ctx, slots, rule, banned)


def local_search(ctx: Ctx, slots, rule: str, banned: set, max_pass: int = 40):
    cost, _ = evaluate_plan(ctx, slots, rule)
    for _ in range(max_pass):
        improved = False
        # 1. drop a shift
        i = 0
        while i < len(slots):
            trial = slots[:i] + slots[i + 1:]
            c, _ = evaluate_plan(ctx, trial, rule)
            if c < cost - 1e-9:
                slots, cost, improved = trial, c, True
            else:
                i += 1
        # 2. swap a shift for another template on its day
        for i in range(len(slots)):
            q, o = slots[i]
            for alt in ctx.options[o.day]:
                if alt is o or alt.tpl.id == o.tpl.id or (q, alt.day, alt.tpl.id) in banned:
                    continue
                trial = slots[:i] + [(q, alt)] + slots[i + 1:]
                c, _ = evaluate_plan(ctx, trial, rule)
                if c < cost - 1e-9:
                    slots, cost, improved = trial, c, True
                    q, o = slots[i]
        # 3. add a shift
        while True:
            best, best_c = None, cost
            for q in ctx.queues:
                for day in ctx.days:
                    for o in ctx.options[day]:
                        if (q, day, o.tpl.id) in banned:
                            continue
                        c, _ = evaluate_plan(ctx, slots + [(q, o)], rule)
                        if c < best_c - 1e-9:
                            best, best_c = (q, o), c
            if best is None:
                break
            slots, cost, improved = slots + [best], best_c, True
        # 4. move a shift to another queue (same day and template)
        for i in range(len(slots)):
            q, o = slots[i]
            for q2 in ctx.queues:
                if q2 == q or (q2, o.day, o.tpl.id) in banned:
                    continue
                trial = slots[:i] + [(q2, o)] + slots[i + 1:]
                c, _ = evaluate_plan(ctx, trial, rule)
                if c < cost - 1e-9:
                    slots, cost, improved = trial, c, True
                    q = q2
        if not improved:
            break
    return slots


# --- assignment ----------------------------------------------------------------------------------------

def assign(ctx: Ctx, slots, agents: list[Agent]):
    """Give each planned shift an agent. Returns (assigned: [(slot index, agent)], unassigned: [slot index])."""
    cfg = ctx.cfg
    caps = cfg["weekly_hours"]
    max_run = cfg["max_consecutive_days"]
    rest = timedelta(hours=float(cfg["min_rest_hours"])) if cfg.get("min_rest_hours") else timedelta(0)
    split_ok = cfg.get("split_contracts")
    hours = defaultdict(float)
    worked: dict[str, list[date]] = defaultdict(list)
    last_end: dict[str, datetime] = {}
    got, left = [], []
    # scarcest first within a day: fewest skilled agents, split shifts (PT only) before the rest
    n_skill = {q: sum(q in a.skills for a in agents) for q in ctx.queues}
    order = sorted(range(len(slots)), key=lambda i: (slots[i][1].day, not slots[i][1].tpl.is_split,
                                                    n_skill[slots[i][0]], slots[i][1].start, slots[i][0], i))
    for i in order:
        q, o = slots[i]
        cands = [a for a in agents
                 if q in a.skills
                 and (not o.tpl.is_split or split_ok is None or a.contract in split_ok)
                 and o.day not in worked[a.agent_id]
                 and hours[a.agent_id] + o.hours <= caps[a.contract] + 1e-9
                 and not _would_exceed_run(worked[a.agent_id], o.day, max_run)
                 and _rest_ok(a.agent_id, o, last_end, worked, rest, got, slots)]
        if not cands:
            left.append(i)
            continue
        # keep an agent on one template shape where possible (stable rosters), then fewest hours
        a = min(cands, key=lambda x: (hours[x.agent_id], x.agent_id))
        got.append((i, a))
        hours[a.agent_id] += o.hours
        worked[a.agent_id].append(o.day)
        last_end[a.agent_id] = max(last_end.get(a.agent_id, o.end), o.end)
    return got, left


def _rest_ok(aid, o: Option, last_end, worked, rest: timedelta, got, slots) -> bool:
    """Elapsed rest to the agent's shifts on the neighbouring days (both directions: slots are not
    assigned strictly in time order)."""
    if not rest:
        return True
    for i, a in got:
        if a.agent_id != aid:
            continue
        p = slots[i][1]
        if p.end <= o.start:
            if o.start - p.end < rest:
                return False
        elif o.end <= p.start:
            if p.start - o.end < rest:
                return False
        else:
            return False
    return True


def schedule_week(req: pd.DataFrame, cfg: dict, agents: list[Agent], week: str) -> list[Shift]:
    if constraints.weight(cfg) and cfg.get("min_cover"):
        raise SystemExit("scheduler 'weekly' counts an agent once, on the queue they are scheduled on: "
                         "set cross_skill_weight: 0 with min_cover")
    ctx = Ctx(req, cfg, week)
    rule = cfg.get("break_rule", "midpoint")
    banned: set = set()
    for _ in range(8):
        slots = plan_week(ctx, banned)
        got, left = assign(ctx, slots, agents)
        if not left:
            break
        for i in left:
            q, o = slots[i]
            banned.add((q, o.day, o.tpl.id))
    # whatever could not be assigned in the final round is left out (reported by the evaluator as shortfall)
    slots_done = [slots[i] for i, _ in got]
    owners = [a for _, a in got]
    cost, info = evaluate_plan(ctx, slots_done, rule)
    shifts = []
    for (q, o), a, ch in zip(slots_done, owners, info["chosen"]):
        sh = Shift(a.agent_id, q, o.tpl, o.day, list(o.segs), [ctx.grid[i] for i in o.idx])
        if ch is not None:
            sh.break_start = ctx.grid[ch[0]]
            sh.break_minutes = int(cfg["break"]["minutes"])
        shifts.append(sh)
    return shifts

