        spare = {q: max_miss.get(q, 10 ** 9) - info["short"][q] for q in ctx.queues}
        relax = set()
        for qs, _, _ in (pool_violations(ctx, hours, agents) if agents else []):
            relax.add(max(qs, key=lambda q: (spare[q], hours[q])))
        if not relax and hours_cap is not None and info["hours"] > hours_cap:
            relax.add(max(ctx.queues, key=lambda q: (spare[q], hours[q])))
        relax = {q for q in relax if idx[q] + 1 < len(LAMBDAS)}
        if not relax:
            return slots
        for q in relax:
            idx[q] += 1


