s=open(p).read()
a=s.index('    cur, cost = list(start), best_c\n    while True:')
b=s.index('LAMBDAS =')
new='''    cur, cost = list(start), best_c
    while True:
        best = (cost, None)
        n = len(cur)
        for stage in (1, 2):
            trials = []
            if stage == 1:                       # single moves: drop, swap, add
                for i in range(n):
                    trials.append(cur[:i] + cur[i + 1:])
                    for o in allowed:
                        if o is not cur[i]:
                            trials.append(cur[:i] + [o] + cur[i + 1:])
                for o in allowed:
                    trials.append(cur + [o])
            else:                                # pair moves: two -> one, one -> two
                for i in range(n):
                    for j in range(i + 1, n):
                        for o in allowed:
                            trials.append([x for k, x in enumerate(cur) if k not in (i, j)] + [o])
                    for o in allowed:
                        for o2 in allowed:
                            trials.append(cur[:i] + cur[i + 1:] + [o, o2])
            for t in trials:
                c = cell_eval(ctx, q, t, lam, rule)[0]
                if c < best[0] - 1e-9:
                    best = (c, t)
            if best[1] is not None:
                break
        if best[1] is None:
            break
        cost, cur = best
    return cur


'''
open(p,'w').write(s[:a]+new+s[b:])
E
